def build(subj, rows, title):
    qs = []
    for i, (tp, q, code, opts, c, ex) in enumerate(rows):
        cs = list(c)
        assert all(x in L[:len(opts)] for x in cs), (subj, i)
        ans = '; '.join('%s) %s' % (x, opts[L.index(x)]) for x in cs)
        item = {'id': 'v92-%s-%d' % (subj, i + 1), 'n': i + 1, 'topic': tp, 'multi': subj == 'db', 'correct': cs, 'q': q,
                'opts': [{'l': L[j], 't': t} for j, t in enumerate(opts)],
                'ex': ('Дұрыс жауап%s — %s. %s' % ('тар' if len(cs) > 1 else '', ans, ex))}
        if code: item['code'] = code
        qs.append(item)
    key = 'v92-%s' % subj
    d = {'key': key, 'variant': 92, 'subject': subj, 'lang': 'kz', 'origLang': 'kz', 'source': 'ai', 'title': title, 'questions': qs}
    open(os.path.join(ROOT, 'data/sets/%s.js' % key), 'w', encoding='utf-8').write('Shyn.addSet(' + json.dumps(d, ensure_ascii=False) + ');\n')
    return key

keys = [build('algo', ALGO, 'Нұсқа 92 · Интенсив: алгоритмдер (спецификациядағы аз тақырыптар)'),
        build('db', DB, 'Нұсқа 92 · Интенсив: деректер қоры (спецификациядағы аз тақырыптар)')]
